-- Codex app-server item coverage includes file changes, MCP calls, and web
-- searches. Keep both audit tables aligned with the canonical event union so
-- auxiliary event persistence cannot reject otherwise valid runtime events.
ALTER TABLE "goat"."local_codex_events" DROP CONSTRAINT IF EXISTS "goat_local_codex_events_type_check";--> statement-breakpoint
ALTER TABLE "goat"."local_codex_events" ADD CONSTRAINT "goat_local_codex_events_type_check" CHECK ("local_codex_events"."type" IN ('assistant.delta', 'assistant.completed', 'reasoning.completed', 'command.started', 'command.output', 'command.completed', 'command.failed', 'file_change.started', 'file_change.completed', 'mcp_tool.started', 'mcp_tool.completed', 'web_search.started', 'web_search.completed', 'plan.updated', 'goal.updated', 'question.requested', 'approval.requested', 'turn.started', 'turn.completed', 'usage.updated', 'error', 'unknown'));--> statement-breakpoint
ALTER TABLE "goat"."codex_chat_events" DROP CONSTRAINT IF EXISTS "goat_codex_chat_events_type_check";--> statement-breakpoint
ALTER TABLE "goat"."codex_chat_events" ADD CONSTRAINT "goat_codex_chat_events_type_check" CHECK ("codex_chat_events"."type" IN ('assistant.completed', 'reasoning.completed', 'command.started', 'command.completed', 'command.failed', 'file_change.started', 'file_change.completed', 'mcp_tool.started', 'mcp_tool.completed', 'web_search.started', 'web_search.completed', 'plan.updated', 'goal.updated', 'question.requested', 'approval.requested', 'turn.started', 'turn.completed', 'usage.updated', 'error', 'unknown'));
